for _k in ("JAKE", "WILLIAMS", "MARTIN", "KYLE", "IAN"): GUESTS.pop(_k, None)

# Fuller facts for prominent guest characters: label -> bullets (replaces the one-liner in GUESTS)
GUEST_FACTS = {
 "SOREN": ["Member of the J'naii, an androgynous species that treats any gender identity as a sickness.", "Identifies as female and falls for Riker while they work together to rescue a shuttle from null space.", "Put on trial and subjected to 'psychotectic' treatment; Riker and Worf's rescue attempt comes too late, and she no longer wants to leave (*The Outcast*)."],
 "RASMUSSEN": ["Arrives in a time pod claiming to be a historian from the 26th century observing a famous mission.", "Actually a failed inventor from 22nd-century New Jersey who stole the pod and plans to 'invent' the devices he pockets from the crew.", "Data catches him in the act; the pod vanishes, stranding him in the 24th century, and he is taken to the brig and dropped at Starbase 214 (*A Matter of Time*)."],
 "NELLA": ["Head of stellar sciences and a pianist, who plays alongside Picard's Ressikan flute.", "Picard plays the Ressikan flute from his Kataan life with her, and shares what the probe gave him.", "Her deflector plan during the Bersallis III evacuation puts her and the perimeter teams at risk; she survives and asks for a transfer (*Lessons*)."],
 "AMANDA": ["Gifted Starfleet intern raised by human foster parents in Kansas.", "Her birth parents were Q who chose to live as humans and were executed by the Continuum; Q arrives to judge whether she is a threat.", "Tries to refuse her powers, then uses them to save the ship and chooses the Continuum (*True Q*)."],
 "KAMALA": ["Kriosian empathic metamorph bred to become whatever her partner desires, intended as a peace gift to Chancellor Alrik of Valt.", "Freed early from stasis by the Ferengi, she bonds with Picard rather than her intended husband.", "Goes through with the marriage anyway, carrying Picard's sense of duty with her (*The Perfect Mate*)."],
 "TIMICIN": ["Kaelon scientist whose life's work is reigniting his world's dying sun.", "Approaching sixty, when Kaelon custom requires the 'Resolution', a ritual death; Lwaxana falls in love with him and begs him to refuse.", "Seeks asylum, then returns home to die with his daughter at his side (*Half a Life*)."],
 "SATIE": ["Retired admiral and daughter of a famous Federation judge, brought in to investigate sabotage in engineering.", "Turns the inquiry into a hunt for conspirators, targeting crewman Simon Tarses over his Romulan grandfather and then Picard himself.", "Undone when Picard quotes her father's words on liberty back to her and Admiral Henry walks out (*The Drumhead*)."],
 "JAMESON": ["Admiral who ended a hostage crisis on Mordan IV forty-five years earlier, secretly by arming both sides and prolonging a civil war.", "Takes a Cerebus II de-ageing drug to lead a new rescue, growing younger by the hour and dying of its effects.", "His wife Anne accompanies him; he is buried on Mordan IV (*Too Short a Season*)."],
 "MARR": ["Xenologist who has studied the Crystalline Entity since it killed the Omicron Theta colonists, including her son Renny.", "Data carries her son's journals in his memory, which she finds both comforting and unbearable.", "Destroys the Entity with a resonating graviton beam against Picard's orders, ending her career (*Silicon Avatar*)."],
 "ALKAR": ["Lumerian ambassador famed for calm mediation, achieved by dumping his negative emotions into a 'receptacle' through a ritual bond.", "His 'mother' was the previous receptacle; he bonds Troi, who ages rapidly and turns aggressive.", "Dies when Crusher fakes Troi's death to break the bond and the backlog of emotion hits him (*Man of the People*)."],
 "PRESSMAN": ["Riker's first captain, on the USS Pegasus, which was lost twelve years earlier after an apparent mutiny.", "Now an admiral, he returns to recover the ship and the illegal phasing cloak he was testing in violation of the Treaty of Algeron.", "Riker finally tells Picard the truth; Pressman is arrested (*The Pegasus*)."],
 "OKONA": ["Captain of the small freighter Erstwhile, a charming rogue wanted by two neighbouring worlds.", "Accused of theft by one and of seducing a daughter by the other; the truth is that he is a go-between for two young lovers.", "His visit prompts Data to study humour with a holodeck comic and Guinan (*The Outrageous Okona*)."],
 "ARDRA": ["Con artist who claims to be Ardra, the devil figure of Ventax II, come to collect on a thousand-year-old contract.", "Uses a cloaked ship, transporters and holograms to fake her powers, including appearing as a devil and extending a cloak over the Enterprise.", "Exposed when Geordi finds her ship and Picard turns her tricks against her in Data's arbitration (*Devil's Due*)."],
 "RAL": ["Part-Betazoid negotiator for the Chrysalians, secretly using his empathic sense to manipulate rivals.", "Seduces Troi and tries to win the Barzan wormhole rights through staged theatrics with the Ferengi.", "Troi exposes his methods in front of the delegates; the wormhole proves worthless anyway (*The Price*)."],
 "JENNA": ["Security officer who plays in Data's musical quintet and, after a break-up with Jeff Arton, starts a relationship with him.", "Data writes a programme for the romance; she ends it on realising nothing she does can make him happy or sad (*In Theory*)."],
 "TIMOTHY": ["Sole survivor of the research vessel Vico, rescued by Data, and blaming himself for the disaster.", "Copes by declaring himself an android and imitating Data in every detail.", "Data helps him accept his grief and his humanity; his memory of the ship's last moments saves the Enterprise (*Hero Worship*)."],
 "TAM": ["Betazoid born with his telepathy fully active, unable to shut out other minds, with a troubled Starfleet record.", "Sent to contact Tin Man, a living ship named Gomtuu that has lost its crew, before the Romulans claim it.", "Chooses to stay inside Gomtuu, each ending the other's loneliness (*Tin Man*)."],
 "ISHARA": ["Tasha's younger sister, still living with the Coalition gang on the failed colony Turkana IV.", "Helps the crew rescue hostages and seems to want a new life, winning Data's trust.", "Uses the mission to disable the rival Alliance's defences and chooses the gang over Tasha's example (*Legacy*)."],
 "TORETH": ["Romulan commander of the warbird Khazara, suspicious of the Tal Shiar officer 'Major Rakal' forced on her.", "Troi, surgically altered to play Rakal, has to outrank and outbluff her to smuggle defectors through.", "Relieved of command when Troi, claiming Tal Shiar authority, has N'Vek disarm and remove her from her station on threat of being shot (*Face of the Enemy*)."],
 "FAJO": ["Zibalian trader and collector of unique objects who kidnaps Data by faking his death in a shuttle explosion.", "Owns an illegal Varon-T disruptor and murders his assistant Varria when she helps Data.", "Data is beamed away as he levels the weapon at him, and it discharges in transit; Fajo ends up in custody with his collection confiscated (*The Most Toys*)."],
 "LAL": ["Android built by Data using a new submicron matrix transfer; chooses to be a human female.", "Attends school, works in Ten Forward, and begins to feel emotions, starting with fear.", "Admiral Haftel's attempt to take her triggers a cascade failure; Data keeps her memories (*The Offspring*)."],
 "JULIANA": ["Noonien Soong's former wife, who raised Data on Omicron Theta and left Soong afterwards.", "Revealed to be an android Soong built after the real Juliana was injured, so faithful she does not know.", "Data decides she should go on believing she is human (*Inheritance*)."],
 "RIKER 2": ["A duplicate created when a transporter beam reflected off Nervala IV's distortion field eight years earlier.", "Survived alone on the planet, still in love with Troi and bitter about the career he lost.", "Takes the name Thomas and a posting on the USS Gandhi (*Second Chances*)."],
 "KYLE RIKER": ["Civilian strategist and widower, estranged from Will for fifteen years.", "Survived a Tholian attack on a starbase and fell in love with Pulaski, though he put his career before marriage.", "Father and son settle it with an anbo-jyutsu bout and an admission that he cheated (*The Icarus Factor*)."],
 "NIKOLAI": ["Worf's human foster brother, a cultural observer on Boraal II who broke the Prime Directive to live among the villagers.", "Smuggles a village onto the holodeck when the planet's atmosphere dies and guides them to a new world.", "Stays with them, expecting a child with a Boraalan woman (*Homeward*)."],
 "K'MTAR": ["Arrives claiming to be gin'tak, a trusted adviser to the House of Mogh sent by Kurn, saying the Duras sisters were behind the attack on Worf's family.", "Actually Alexander himself, forty years older, come back to make the boy a warrior and prevent Worf's future death.", "Worf refuses to change his son, and K'mtar leaves (*Firstborn*)."],
 "DATHON": ["Captain of the Tamarian ship whose language consists of allusions to their myths.", "Strands himself and Picard on El-Adrel IV to face a beast together, as in 'Darmok and Jalad at Tanagra'.", "Dies of his wounds, but Picard learns enough to stop a battle between the ships (*Darmok*)."],
 "MADDOX": ["Cyberneticist at the Daystrom Institute who opposed Data's entry to Starfleet Academy.", "Seeks to disassemble Data to learn how to build more; Riker is forced to prosecute and Picard to defend.", "Loses the hearing, and later becomes a correspondent of Data's (*The Measure of a Man*, *Data's Day*)."],
 "LOCARNO": ["Leader of Nova Squadron at the Academy, whose attempt at the banned Kolvoord Starburst kills cadet Joshua Albert.", "Pressures Wesley and the others to cover it up.", "Takes full responsibility once Wesley speaks and is expelled (*The First Duty*)."],
 "SITO": ["Bajoran cadet in Nova Squadron, allowed to stay after the cover-up.", "Later posted to the Enterprise, where Picard first tests her with harsh words and then trusts her with a covert mission.", "Poses as a prisoner to return a Cardassian defector and is reported killed; Picard announces her loss to the crew (*Lower Decks*)."],
 "DURAS": ["Klingon councillor from a powerful house; his father Ja'rod betrayed Khitomer to the Romulans.", "Has Worf's father blamed instead, and K'Ehleyr murdered when she uncovers the truth.", "Challenged and killed by Worf under the right of vengeance (*Sins of the Father*, *Reunion*)."],
 "MADRED": ["Cardassian interrogator who tortures Picard for Federation defence plans using an implanted pain device.", "Shows Picard four lights and insists there are five; brings his young daughter to the sessions.", "Picard later admits to Troi that he had been about to say he saw five (*Chain of Command*)."],
 "MAXWELL": ["Captain of the USS Phoenix and O'Brien's former commander on the Rutledge, whose family died at Setlik III.", "Destroys Cardassian ships he believes are rearming for war, in defiance of the treaty.", "O'Brien talks him into surrendering; Picard tells the Cardassian Macet that Maxwell was right (*The Wounded*)."],
 "K'MPEC": ["Chancellor of the Klingon High Council, slowly poisoned (Veridium six in his wine) by either Gowron or Duras.", "Names Picard Arbiter of Succession because no one on the Council can be trusted, and asks him to find which rival poisoned him (*Reunion*)."],
 "SELA": ["Romulan commander whose mother was the Tasha Yar of the alternate timeline, captured when the Enterprise-C went back in time.", "Her mother was executed trying to escape with her; Sela regards herself as entirely Romulan.", "Backs the Duras family in the Klingon civil war and leads the plot to invade Vulcan under cover of Spock's reunification movement (*Redemption*, *Unification*)."],
}
